FORMAL, CASUAL = 0, 1


def load_pairwise(path, nli_threshold=0.90):
    raw = []
    with open(path) as f:
        for line in f:
            if line.strip():
                raw.append(json.loads(line))
    raw = [d for d in raw if d.get("nli_cf", 0) >= nli_threshold]

    comparisons = []
    pair_groups = {}

    for rec in raw:
